                    'tables_write' => [
                        ['name' => 'ftr_dp', 'actions' => ['insert', 'update'], 'desc' => 'Header FTR DP (no_ftr_dp, tanggal, supplier, No PO/PI, total, nilai DP, balance, mata uang) — dibuat saat simpan, status diperbarui saat approve/cancel.'],
