                        ['name' => 'tbl_debitnote_h', 'desc' => 'Header Debit Note, pengurang saldo.'],
                        ['name' => 'tbl_debitnote_det', 'desc' => 'Detail Debit Note.'],
                        ['name' => 'tbl_alokasi', 'desc' => 'Header alokasi Debit Note ke dokumen sumber.'],
